 5. Configuration és Parsing

 TOML Parser (toml crate)
 Funkció: TOML config parsing[22]
 LoC becslés: ~5,000+
 Implementációs idő: 1 hét

Zig Implementáció:
zig
// zig-toml library [web:81]
const toml = @import("toml");

const Config = struct {
    model: []const u8,
    base_url: []const u8,
    max_tokens: u32,
};

pub fn loadConfig(allocator: std.mem.Allocator, path: []const u8) !Config {
    const file = try std.fs.cwd().openFile(path, .{});
    defer file.close();

    const content = try file.readToEndAlloc(allocator, 1024 * 1024);
    defer allocator.free(content);

    return try toml.parse(Config, allocator, content);
}


