 Base64, Blake3, SHA (crypto)
 Funkció: Hashing, encoding
 LoC becslés összesen: ~10,000+
 Implementációs idő: 1 hét

Zig Implementáció:
zig
// Zig std.crypto
const crypto = std.crypto;

pub fn hashBlake3(data: []const u8) [32]u8 {
    var hasher = crypto.hash.blake3.Blake3.init(.{});
    hasher.update(data);
    var out: [32]u8 = undefined;
    hasher.final(&out);
    return out;
}

// Base64
const base64 = std.base64;
pub fn encodeBase64(allocator: std.mem.Allocator, data: []const u8) ![]u8 {
    const encoder = base64.standard.Encoder;
    const encoded_len = encoder.calcSize(data.len);
    const buffer = try allocator.alloc(u8, encoded_len);
    return encoder.encode(buffer, data);
}


