 Cerebras GLM Specifikus Kód (Legfontosabb!)

zig
// cerebras.zig - A SZÍVE a projektnek
const std = @import("std");
const http = std.http;

pub const CerebrasClient = struct {
    allocator: std.mem.Allocator,
    api_key: []const u8,
    base_url: []const u8 = "https://inference.cerebras.ai/v1",

    pub fn init(allocator: std.mem.Allocator, api_key: []const u8) CerebrasClient {
        return .{
            .allocator = allocator,
            .api_key = api_key,
        };
    }

    pub fn chatCompletion(self: *CerebrasClient, messages: []Message) !Response {
        const uri = try std.Uri.parse(self.base_url ++ "/chat/completions");

        var client = http.Client{ .allocator = self.allocator };
        defer client.deinit();

        var headers = http.Headers{ .allocator = self.allocator };
        defer headers.deinit();

        try headers.append("Authorization", try std.fmt.allocPrint(
            self.allocator, "Bearer {s}", .{self.api_key}
        ));
        try headers.append("Content-Type", "application/json");

        const body = try std.json.stringifyAlloc(self.allocator, .{
            .model = "zai-glm-4.7",
            .messages = messages,
            .max_tokens = 40000,
            .stream = true,
        }, .{});
        defer self.allocator.free(body);

        var req = try client.open(.POST, uri, headers, .{});
        defer req.deinit();

        try req.send();
        try req.writeAll(body);
        try req.finish();
        try req.wait();

        // Stream response handling...
        return try self.parseStreamingResponse(&req);
    }

    fn parseStreamingResponse(self: *CerebrasClient, req: *http.Client.Request) !Response {
        var reader = req.reader();
        var buffer: [4096]u8 = undefined;

        while (try reader.readUntilDelimiterOrEof(&buffer, '\n')) |line| {
            if (std.mem.startsWith(u8, line, "data: ")) {
                const json_data = line[6..];
                // Parse SSE chunk...
            }
        }

        return Response{ /* ... */ };
    }
};

pub const Message = struct {
    role: []const u8,
    content: []const u8,
};

pub const Response = struct {
    content: []const u8,
    tokens_used: u32,
};


 Build System (build.zig)

zig
const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    // Dependencies
    const httpz = b.dependency("httpz", .{
        .target = target,
        .optimize = optimize,
    });

    const zig_toml = b.dependency("zig-toml", .{
        .target = target,
        .optimize = optimize,
    });

    // Main executable
    const exe = b.addExecutable(.{
        .name = "codex-zig",
        .root_source_file = .{ .path = "src/main.zig" },
        .target = target,
        .optimize = optimize,
    });

    exe.root_module.addImport("httpz", httpz.module("httpz"));
    exe.root_module.addImport("toml", zig_toml.module("zig-toml"));

    // Link libc (ha kell C library binding)
    exe.linkLibC();

    b.installArtifact(exe);

    // Run command
    const run_cmd = b.addRunArtifact(exe);
    run_cmd.step.dependOn(b.getInstallStep());

    const run_step = b.step("run", "Run codex-zig");
    run_step.dependOn(&run_cmd.step);

    // Tests
    const tests = b.addTest(.{
        .root_source_file = .{ .path = "src/tests.zig" },
        .target = target,
        .optimize = optimize,
    });

    const test_step = b.step("test", "Run tests");
    test_step.dependOn(&b.addRunArtifact(tests).step);
}


